import {StructuredNoteContentAdapter,STRUCTURED_NOTE_CONTENT_ADAPTER_CONTRACT,STRUCTURED_NOTE_CONTENT_ADAPTER_OWNER,createStructuredNoteContentDocument,isCanonicalStructuredNoteContentAdapter,structuredNoteContentAdapterPublicationCount} from './adapters/structured-note-content.js';
import {createStructuredNoteContentCompatibilityAdapter,NOTE_CONTENT_COMPATIBILITY_CONTRACT} from './adapters/structured-note-content-compatibility.js';
import {NoteBindingAdapter} from './foundation/notes/note-binding.js';
import {libraryNoteBindingInput,learnNoteBindingInput,spatialNoteBindingInput} from './adapters/note-binding-domains.js';
import {StickyNoteWindowOwner} from './foundation/notes/sticky-note-window.js';
import {createStructuredConsumerAdapter} from './adapters/structured-documents.js';
import {FIXTURES,STRUCTURE_TREE,NOTE_FIXTURES} from './adapters/library-fixtures.js';
import {SemanticCommandBus} from './foundation/global/commands.js';
import {GlobalInputKeymapOwner} from './foundation/global/input-keymap.js';
