  cases.push(run('04.canonical-tree-insert-update-remove-parity',()=>{const n=makeNote(),before=n.adapter.snapshot(),insertId=`${n.noteId}-inserted`;n.adapter.insertBlock({id:insertId,type:'paragraph',html:'inserted'});assert(n.adapter.findBlockRef(insertId),'insert failed');n.host.updateContent(insertId,{html:'updated'});assert(n.adapter.findBlockRef(insertId).block.html==='updated','update failed');n.adapter.removeBlock(insertId);assert(!n.adapter.findBlockRef(insertId),'remove failed');assert(n.adapter.treeKernel===STRUCTURED_TREE_KERNEL&&n.adapter.mutationKernel===STRUCTURED_MUTATION_KERNEL,'canonical engine bypass');return {treeOwner:n.adapter.treeKernel.owner,mutationOwner:n.adapter.mutationKernel.owner,historyFrames:n.adapter.transactionDescriptor().historyLength,baselineDocumentId:before.id}}));
  cases.push(run('05.history-undo-redo-parity',()=>{const n=makeNote(),before=n.adapter.snapshot(),tx0=n.adapter.transactionDescriptor();n.host.updateContent(n.ids.paragraph,{html:'history update'});const changed=n.adapter.snapshot(),tx1=n.adapter.transactionDescriptor();const undo=n.adapter.undo();assert(undo.changed&&stable(n.adapter.snapshot())===stable(before),'undo not exact');const redo=n.adapter.redo();assert(redo.changed&&stable(n.adapter.snapshot())===stable(changed),'redo not exact');return {owner:n.adapter.transactionOwner.owner,historyDelta:tx1.historyLength-tx0.historyLength,undo:undo.status,redo:redo.status}}));
  cases.push(run('06.recovery-boundary-parity',()=>{const n=makeNote();n.host.updateContent(n.ids.paragraph,{html:'recovery state'});const record=n.adapter.captureRecovery('w6c-proof'),before=n.adapter.snapshot();n.host.updateContent(n.ids.paragraph,{html:'later state'});const restored=n.adapter.recoverAsNew(record.id);assert(stable(restored)===stable(before),'recovery did not restore captured canonical document');return {owner:n.adapter.transactionOwner.owner,recoveryId:record.id,recovered:true,persistenceClaimed:false}}));
  cases.push(run('07.selection-parity',()=>{const n=makeNote(),result=n.host.routePointerSelection(n.ids.paragraph);assert(result.owner==='StructuredSelectionKernel'&&result.delegatedOwner==='StructuredSelectionKernel'&&result.blockIds.includes(n.ids.paragraph),'selection bypass');return {owner:result.owner,selected:result.blockIds,documentId:n.adapter.identity().id}}));
  cases.push(run('08.clipboard-copy-cut-paste-parity',()=>{const copyNote=makeNote('library',{noteId:'w6c-copy-note'});copyNote.host.routePointerSelection(copyNote.ids.paragraph);const beforeCopy=stable(copyNote.adapter.snapshot()),copied=copyNote.host.routeClipboard('document.copy');assert(copied.ok&&copied.owner==='StructuredClipboardTrustOwner'&&stable(copyNote.adapter.snapshot())===beforeCopy,'copy mutated/bypassed');const cutNote=makeNote('library',{noteId:'w6c-cut-note'});cutNote.host.routePointerSelection(cutNote.ids.bullet2);const cut=cutNote.host.routeClipboard('document.cut');assert(cut.ok&&cut.owner==='StructuredClipboardTrustOwner'&&!cutNote.adapter.findBlockRef(cutNote.ids.bullet2),'cut did not route canonical clipboard');cutNote.adapter.undo();assert(cutNote.adapter.findBlockRef(cutNote.ids.bullet2),'cut undo failed');const pasteSource=makeNote('library',{noteId:'w6c-paste-source'});pasteSource.host.routePointerSelection(pasteSource.ids.paragraph);const payload=pasteSource.host.routeClipboard('document.copy').payload,pasteNote=makeNote('library',{noteId:'w6c-paste-note'}),tx0=pasteNote.adapter.transactionDescriptor(),paste=pasteNote.host.routeClipboard('document.paste',{payload,index:pasteNote.adapter.snapshot().blocks.length}),tx1=pasteNote.adapter.transactionDescriptor();assert(Array.isArray(paste.inserted)&&paste.inserted.length===1&&paste.delegatedOwner==='StructuredClipboardTrustOwner'&&tx1.historyLength===tx0.historyLength+1,'paste not transactional');return {owner:'StructuredClipboardTrustOwner',copyNoMutation:true,cutUndo:true,pasteHistoryDelta:1}}));
