  cases.push(run('12.ime-composition-safety-parity',()=>{const n=makeNote(),before=stable(n.adapter.snapshot()),start=n.host.routeComposition('start',{data:'م'},{caret:{blockId:n.ids.paragraph,beforeText:'',afterText:'',beforeHtml:'',afterHtml:'',atStart:true,atEnd:true}}),keydown=n.host.routeKeydown(eventFor('Enter',{isComposing:true}),{caret:{blockId:n.ids.paragraph,beforeText:'م',afterText:'',beforeHtml:'م',afterHtml:'',atStart:false,atEnd:true}}),end=n.host.routeComposition('end',{data:'مرحبا'});assert(start.code==='IME_COMPOSITION_STARTED'&&keydown.globalResult.code==='IME_COMPOSITION_PASSTHROUGH'&&keydown.result.code==='GLOBAL_ROUTE_RESERVED'&&end.code==='IME_COMPOSITION_ENDED'&&stable(n.adapter.snapshot())===before,'IME safety failed');return {start:start.code,globalDuring:keydown.globalResult.code,structuredDuring:keydown.result.code,end:end.code,documentUnchanged:true}}));
