  cases.push(run('14.direction-bidi-parity',()=>{const n=makeNote(),node=n.host.renderer.find(n.host.project().render,n.ids.paragraph);assert(node.directionOwner==='InputDirectionResolver'&&node.richContentOwner==='StructuredRichContentOwner'&&['rtl','ltr'].includes(node.direction)&&node.html.includes('TCP/IP'),'Bidi projection failed');return {direction:node.direction,directionOwner:node.directionOwner,richOwner:node.richContentOwner,technicalTokenPreserved:node.html.includes('TCP/IP')}}));
