  cases.push(run('18.renderer-host-projection-parity',()=>{const n=makeNote(),projection=n.content.project();assert(n.host.renderer.constructor===StructuredBlockRenderer&&n.host.presentationBridge.constructor===StructuredPresentationBridge&&projection.content.owner==='StructuredSurfaceHost'&&projection.content.documentId===n.adapter.identity().id,'host/renderer path diverged');return {host:projection.content.owner,renderer:n.host.renderer.owner,presentation:n.host.presentationBridge.owner,documentId:projection.documentId}}));
