  cases.push(run('23.stale-unresolved-binding-preserves-note-content',()=>{const noteId='w6c-stale',bindingOwner=new NoteBindingAdapter();bindingOwner.bind(noteId,libraryNoteBindingInput({noteId,documentId:'KU-D05-0021',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:{state:'stale',reason:'offline'}}));const n=makeNote('library',{noteId,bindingOwner}),before=stable(n.adapter.snapshot()),tx=stable(n.adapter.transactionDescriptor());bindingOwner.projectAvailability(noteId,{availability:{state:'unresolved',reason:'resolver-pending'}});assert(stable(n.adapter.snapshot())===before&&stable(n.adapter.transactionDescriptor())===tx&&n.content.bindingDescriptor().availability.state==='unresolved','binding status changed note content');return {contentUnchanged:true,historyUnchanged:true,availability:'unresolved'}}));
  cases.push(run('24.binding-reresolution-does-not-replace-engine',()=>{const noteId='w6c-reresolve',bindingOwner=new NoteBindingAdapter();bindingOwner.bind(noteId,libraryNoteBindingInput({noteId,documentId:'KU-D05-0021',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:{state:'stale',reason:'offline'}}));const n=makeNote('library',{noteId,bindingOwner}),adapter=n.adapter,host=n.host,beforeDoc=stable(n.adapter.snapshot());bindingOwner.projectAvailability(noteId,{source:{documentId:'KU-D05-0021',blockId:'blk-d05-p1'},availability:{state:'available',evidence:{validated:true,resolver:'back'}}});const binding=n.content.bindingDescriptor();assert(binding.availability.state==='available'&&n.content.documentAdapter===adapter&&n.content.surfaceHost===host&&stable(n.adapter.snapshot())===beforeDoc,'re-resolution replaced engine/content');return {availability:'available',sameDocumentAdapter:true,sameHost:true,contentUnchanged:true}}));
  cases.push(run('25.hide-reopen-preserves-content-history-binding-document-identity',()=>{const n=makeNote('library',{noteId:'w6c-hide-reopen'});n.host.updateContent(n.ids.paragraph,{html:'persist in memory'});const doc=stable(n.adapter.snapshot()),tx=stable(n.adapter.transactionDescriptor()),binding=stable(n.content.bindingDescriptor()),docId=n.adapter.identity().id,presentationId=n.windowOwner.window(n.noteId).presentationId;n.windowOwner.hide(n.noteId);assert(stable(n.adapter.snapshot())===doc&&stable(n.adapter.transactionDescriptor())===tx&&stable(n.content.bindingDescriptor())===binding,'hide changed content/history/binding');const reopened=n.windowOwner.open(n.noteId);assert(reopened.presentationId===presentationId&&n.adapter.identity().id===docId&&stable(n.content.bindingDescriptor())===binding,'reopen identity drift');return {documentId:docId,presentationId,bindingStable:true,historyStable:true}}));
  cases.push(run('26.window-geometry-z-pin-do-not-mutate-structured-content',()=>{const n=makeNote('library',{noteId:'w6c-window-isolation'}),beforeDoc=stable(n.adapter.snapshot()),beforeTx=stable(n.adapter.transactionDescriptor());n.windowOwner.setGeometry(n.noteId,{x:200,y:170,width:500,height:360});n.windowOwner.setPinned(n.noteId,true);n.windowOwner.activate(n.noteId);assert(stable(n.adapter.snapshot())===beforeDoc&&stable(n.adapter.transactionDescriptor())===beforeTx,'window operations mutated Structured content');return {contentUnchanged:true,transactionUnchanged:true,window:n.windowOwner.window(n.noteId)}}));
  cases.push(run('27.content-mutation-does-not-mutate-window-state',()=>{const n=makeNote('library',{noteId:'w6c-content-window'}),before=n.windowOwner.window(n.noteId),projection={geometry:stable(before.geometry),pinned:before.pinned,zOrder:before.zOrder,platform:stable(before.platform),presentationId:before.presentationId};n.host.updateContent(n.ids.paragraph,{html:'content-only mutation'});const after=n.windowOwner.window(n.noteId);assert(stable(after.geometry)===projection.geometry&&after.pinned===projection.pinned&&after.zOrder===projection.zOrder&&stable(after.platform)===projection.platform&&after.presentationId===projection.presentationId,'content mutation changed window state');return {windowPresentationUnchanged:true,workingRevision:n.adapter.workingRevision}}));
  cases.push(run('28.separate-window-reuses-same-content-binding-engine',()=>{const bridge={id:'w6c-separate-bridge',capabilities:()=>({alwaysOnTop:false,separateWindow:true}),requestSeparateWindow:()=>({ok:true,active:true})},n=makeNote('library',{noteId:'w6c-separate',capabilityBridge:bridge}),adapter=n.adapter,host=n.host,binding=stable(n.content.bindingDescriptor()),docId=n.adapter.identity().id,result=n.windowOwner.requestSeparateWindow(n.noteId),projection=n.content.presentationBinding({windowInstanceId:'native-window-01'});assert(result.ok&&projection.presentation.hostKind==='separate-window'&&projection.presentation.windowInstanceId==='native-window-01'&&stable(projection.binding)===binding&&n.content.documentAdapter===adapter&&n.content.surfaceHost===host&&n.adapter.identity().id===docId,'separate window created second engine/binding');return {sameDocumentAdapter:true,sameHost:true,sameBinding:true,documentId:docId,presentation:projection.presentation}}));
  cases.push(run('29.os-always-on-top-remains-window-owner-capability-truth',()=>{const n=makeNote('library',{noteId:'w6c-platform-truth'}),before=stable(n.adapter.snapshot()),request=n.windowOwner.requestAlwaysOnTop(n.noteId,true),after=n.content.project();assert(request.ok===false&&request.code==='UNAVAILABLE'&&after.window.platform.alwaysOnTop.availability==='UNAVAILABLE'&&after.window.platform.alwaysOnTop.active===false&&stable(n.adapter.snapshot())===before,'adapter fabricated native always-on-top');return {code:request.code,availability:after.window.platform.alwaysOnTop.availability,contentUnchanged:true}}));

  cases.push(run('30.two-note-isolation',()=>{const bindingOwner=new NoteBindingAdapter(),windowOwner=new StickyNoteWindowOwner({hostGraph:{}}),aId='w6c-note-A',bId='w6c-note-B';bindingOwner.bind(aId,libraryNoteBindingInput({noteId:aId,documentId:'KU-D05-0021',blockId:'blk-d05-p1',route:'PERSONAL:CEP/library',availability:available('A')}));bindingOwner.bind(bId,learnNoteBindingInput({noteId:bId,documentId:'learn-doc',blockId:'learn-p1',route:'PERSONAL:CEP/learn',availability:available('B')}));windowOwner.register(aId);windowOwner.register(bId);const a=makeNote('library',{noteId:aId,bindingOwner,windowOwner}),b=makeNote('learn',{noteId:bId,bindingOwner,windowOwner}),bBefore={doc:stable(b.adapter.snapshot()),tx:stable(b.adapter.transactionDescriptor()),selection:stable(b.adapter.selectedFragmentIdentity()),binding:stable(b.content.bindingDescriptor()),window:stable(windowOwner.window(bId))};a.host.routePointerSelection(a.ids.paragraph);a.host.updateContent(a.ids.paragraph,{html:'A changed'});windowOwner.setPinned(aId,true);assert(stable(b.adapter.snapshot())===bBefore.doc&&stable(b.adapter.transactionDescriptor())===bBefore.tx&&stable(b.adapter.selectedFragmentIdentity())===bBefore.selection&&stable(b.content.bindingDescriptor())===bBefore.binding&&stable(windowOwner.window(bId))===bBefore.window,'note-local state leaked');assert(a.adapter!==b.adapter&&a.adapter.transactionOwner!==b.adapter.transactionOwner&&a.adapter.selection!==b.adapter.selection&&a.adapter.identity().id!==b.adapter.identity().id&&a.noteId!==b.noteId,'document-local owner/state unexpectedly shared');return {documents:[a.adapter.identity().id,b.adapter.identity().id],transactionOwnersDistinct:true,selectionOwnersDistinct:true,bindingEntriesDistinct:true,windowIdentitiesDistinct:true}}));

  cases.push(run('31.fake-note-binding-owner-rejected-fail-atomic',()=>{const before=structuredNoteContentAdapterPublicationCount(),windowOwner=new StickyNoteWindowOwner({hostGraph:{}});windowOwner.register('fake-binding');const message=rejects(()=>new StructuredNoteContentAdapter({noteId:'fake-binding',document:noteDocument('fake-binding'),bindingOwner:{owner:'NoteBindingAdapter',descriptor:()=>({noteId:'fake-binding'})},windowOwner}),'NON_CANONICAL_NOTE_BINDING_OWNER');assert(structuredNoteContentAdapterPublicationCount()===before,'phantom adapter published');return {message,publicationCountUnchanged:true}}));
