  cases.push(run('37.presentation-id-source-substitution-rejected-fail-atomic',()=>{const noteId='presentation-source',windowOwner=new StickyNoteWindowOwner({hostGraph:{}});const window=windowOwner.register(noteId),bindingOwner=new NoteBindingAdapter();bindingOwner.bind(noteId,libraryNoteBindingInput({noteId,documentId:window.presentationId,route:'PERSONAL:CEP/library',availability:available('BAD_SUBSTITUTION')}));const before=structuredNoteContentAdapterPublicationCount(),message=rejects(()=>new StructuredNoteContentAdapter({noteId,document:noteDocument(noteId),bindingOwner,windowOwner}),'PRESENTATION_IDENTITY_CANNOT_BECOME_NOTE_SOURCE_IDENTITY');assert(structuredNoteContentAdapterPublicationCount()===before,'phantom adapter published');return {message,publicationCountUnchanged:true}}));
  cases.push(run('38.presentation-id-document-substitution-rejected-fail-atomic',()=>{const noteId='presentation-document',bindingOwner=new NoteBindingAdapter();bindingOwner.bind(noteId,bindingInput('library',noteId));const windowOwner=new StickyNoteWindowOwner({hostGraph:{}}),window=windowOwner.register(noteId),document=noteDocument(noteId);document.id=window.presentationId;const before=structuredNoteContentAdapterPublicationCount(),message=rejects(()=>new StructuredNoteContentAdapter({noteId,document,bindingOwner,windowOwner}),'PRESENTATION_IDENTITY_CANNOT_BECOME_NOTE_DOCUMENT_IDENTITY');assert(structuredNoteContentAdapterPublicationCount()===before,'phantom adapter published');return {message,publicationCountUnchanged:true}}));
